// The form puts every uploaded file on ONE item (Documents_0, Documents_1, ...).
// The HTTP Request node sends one binary field per request, so make one item per file.
const out = [];
for (const item of $input.all()) {
  const keys = Object.keys(item.binary ?? {}).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
  for (const key of keys) {
    out.push({
      json: { fileNumber: out.length + 1, fileName: item.binary[key].fileName ?? `file ${out.length + 1}` },
      binary: { file: item.binary[key] },
    });
  }
}
if (out.length === 0) throw new Error('No files were uploaded');
return out;

// One row per document. Aadhaar numbers are masked before anything leaves this machine.
const TYPES = { passport: 'Passport', idCard: 'Aadhaar', taxReturn: 'Tax return', panCard: 'PAN card', unknown: 'Unknown' };
const LABELS = { passportNumber: 'Passport no.', expiryDate: 'Expiry', address: 'Address', assessmentYear: 'Assessment year',
  taxPayerName: 'Taxpayer', totalIncome: 'Total income', taxPaid: 'Tax paid', taxDue: 'Tax due', fatherName: 'Father' };
const mask = (n) => (typeof n === 'string' && /\d{4}$/.test(n) ? `XXXX-XXXX-${n.slice(-4)}` : n);
const files = $('One item per file').all();
const processedAt = $now.toFormat('yyyy-MM-dd HH:mm:ss'); // n8n's timezone (GENERIC_TIMEZONE)

const rows = [];
$input.all().forEach((item, i) => {
  const file = files[i]?.json ?? {};
  const base = { 'Processed at': processedAt, 'File': file.fileName ?? '', 'Owner': '', 'Type': '', 'Document name': '',
    'ID number': '', 'Date of birth': '', 'Details': '', 'Error': '' };
  // n8n splits a JSON array response into items: with one file per request, each item is one owner group.
  if (!Array.isArray(item.json.documents)) {
    // The HTTP node returned an error (for example 401, 429 or 503) instead of results.
    const raw = String(item.json.error?.message ?? item.json.message ?? 'request failed');
    // n8n reports e.g. 401 - "{\"detail\":\"missing or invalid API key\"}": keep the status and the API's detail.
    const status = raw.match(/^(\d{3})\b/)?.[1];
    const detail = raw.match(/detail\\?"\s*:\s*\\?"([^"\\]+)/)?.[1];
    const message = status ? `HTTP ${status}${detail ? `: ${detail}` : ''}` : raw;
    rows.push({ ...base, Type: 'Unknown', Error: message.slice(0, 300) });
    return;
  }
  for (const group of [item.json]) {
    for (const doc of group.documents) {
      const data = doc.data ?? {};
      const id = data.passportNumber ?? mask(data.aadharNumber) ?? data.panNumber ?? '';
      const details = Object.entries(data)
        .filter(([k]) => !['passportNumber', 'aadharNumber', 'panNumber', 'dateOfBirth'].includes(k))
        .map(([k, v]) => `${LABELS[k] ?? k}: ${v ?? 'not visible'}`).join('; ');
      rows.push({ ...base, Owner: group.ownerName ?? '', Type: TYPES[doc.documentType] ?? doc.documentType,
        'Document name': doc.documentName ?? '', 'ID number': id ?? '', 'Date of birth': data.dateOfBirth ?? '',
        Details: details, Error: doc.error ?? '' });
    }
  }
});
return rows.map((json) => ({ json }));

// Text for the form's last page. Values come from documents, so escape them.
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const rows = $('Rows for Sheets').all().map((i) => i.json);
const owners = new Map();
for (const r of rows) {
  if (r.Error && !r.Owner) continue;
  const key = (r.Owner || 'No owner found').toLowerCase();
  if (!owners.has(key)) owners.set(key, { name: r.Owner || 'No owner found', types: [] });
  owners.get(key).types.push(r.Type);
}
const problems = rows.filter((r) => r.Error);
const lines = [...owners.values()].map((o) => `${esc(o.name)}: ${esc(o.types.join(', '))}`);
if (problems.length) lines.push(`Problems: ${problems.map((r) => `${esc(r.File)} (${esc(r.Error)})`).join('; ')}`);
return [{ json: { title: `${rows.length} document${rows.length === 1 ? '' : 's'} processed`, message: lines.join(' | ') || 'No documents' } }];
